contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfter = address(c).balance;

        assert(!reverted && balAfter == 0 && contractBalBefore - contractBalAfter == balBefore && balBefore == amount);
    }

    receive() external payable {}
}

